"""Telemetry contract: the server allowlist equals what the client can emit, and every key family in the
schema is recorded by real code.

* telemetry/allowed-keys.json is generated by `python3 plugins/atlas/scripts/atlas_analytics.py allowed-keys`.
  Renaming a skill, hook or agent, or adding one, changes that output; this test fails until the file is
  regenerated, so the ingest server never rejects (or silently accepts) a key the client sends.
* Every pattern of every family in contracts/analytics-schema.json has a recording call site in shipped code
  (grep-based: a needle in the file that records it). A new pattern fails here until a call site is listed.
"""

from __future__ import annotations

import _test_isolation  # noqa: F401  (must be first: redirects ATLAS_HOME)

import json
import subprocess
import sys
from pathlib import Path

import pytest

import atlas_analytics as A

PLUGIN = Path(__file__).resolve().parent.parent
ALLOWED = PLUGIN.parent.parent / "telemetry" / "allowed-keys.json"
REGEN = "python3 plugins/atlas/scripts/atlas_analytics.py allowed-keys > telemetry/allowed-keys.json"

# pattern -> [(file under plugins/atlas, needle that must appear in it)]. The file is the one that records.
CALL_SITES = {
    "session.{harness}": [
        ("hooks/session_boot_core.py", "on_session_start"),
        ("scripts/atlas_analytics.py", '"session." +'),
    ],
    "hook.{hook}.{decision}": [
        ("hooks/event_dispatch.py", '"hook.%s.deny"'),
        ("hooks/event_dispatch.py", '"hook.%s.%s" % (name, decision)'),
        ("hooks/event_dispatch.py", '"hook.%s.context"'),
        ("hooks/event_dispatch.py", '"hook.%s.slow"'),
        ("hooks/event_dispatch.py", '"hook.%s.fault"'),
    ],
    "hook.{hook}.{decision}.{reason}": [
        ("hooks/git_guard.py", '"hook.git_guard.%s.%s"'),
        ("hooks/edit_read_nudge.py", '"hook.edit_read_nudge.context.unread"'),
    ],
    "dispatch.{event}.ms.{ms}": [("hooks/event_dispatch.py", '"dispatch.%s.ms.%s"')],
    "skill.{skill}": [
        ("hooks/event_dispatch.py", '"skill." +'),
        ("hooks/event_dispatch.py", "def prompt_skill_key"),
    ],
    "agent.{role}": [("hooks/event_dispatch.py", '"agent." +')],
    "team.{class}.{effort}": [
        ("scripts/atlas_mux.py", "f\"team.{rec['class']}.{rec['effort']}\"")
    ],
    "team.size.{size}": [("scripts/atlas_mux.py", 'f"team.size.')],
    "team.outcome.{outcome}": [("scripts/atlas_mux.py", '"team.outcome." +')],
    "team.wall.{wall}": [("scripts/atlas_mux.py", '"team.wall." +')],
    "gate.{letter}.block": [
        ("hooks/completion_gate_core.py", 'f"gate.{letter.lower()}.block"')
    ],
    "gate.pass": [("hooks/completion_gate_core.py", '["gate.pass"]')],
    "git.clean.{cleaned}": [
        ("scripts/atlas_git.py", '"git.clean.worktrees"'),
        ("scripts/atlas_git.py", '"git.clean.remote"'),
    ],
    "git.branch.{branchop}": [
        ("scripts/atlas_git.py", '"git.branch.created"'),
        ("scripts/atlas_git.py", '"git.branch.reused"'),
    ],
    "security.alerts.{alertkind}.{severity}": [
        ("scripts/atlas_security.py", "security.alerts.")
    ],
}
# Declared in the schema but with no call site yet.
KNOWN_UNWIRED: set[str] = set()


def _patterns() -> set[str]:
    return {p for fam in A.load_schema()["families"].values() for p in fam["patterns"]}


@pytest.mark.skipif(
    not ALLOWED.parent.is_dir(), reason="telemetry/ is not part of this checkout"
)
def test_allowed_keys_file_equals_current_client_output():
    cli = subprocess.run(
        [
            sys.executable,
            str(PLUGIN / "scripts" / "atlas_analytics.py"),
            "allowed-keys",
        ],
        capture_output=True,
        text=True,
        check=True,
    )
    want = json.loads(cli.stdout)
    have = json.loads(ALLOWED.read_text(encoding="utf-8"))
    missing = sorted(set(want["keys"]) - set(have["keys"]))
    extra = sorted(set(have["keys"]) - set(want["keys"]))
    assert not missing and not extra, (
        f"telemetry/allowed-keys.json is stale: {len(missing)} key(s) the client can send are missing "
        f"({missing[:5]}), {len(extra)} are no longer sent ({extra[:5]}). Regenerate: {REGEN}"
    )
    assert have == want, f"envelope differs from the client output; regenerate: {REGEN}"
    assert have["keys"] == sorted(have["keys"])
    assert ALLOWED.read_text(encoding="utf-8") == cli.stdout, (
        f"formatting differs; regenerate: {REGEN}"
    )


def test_allowed_keys_match_in_process_expansion():
    assert A.allowed_keys() == sorted(set(A.allowed_keys()))
    assert all(A.valid_key(k) for k in A.allowed_keys())


def test_every_schema_pattern_has_a_call_site_or_is_listed_as_unwired():
    patterns = _patterns()
    assert patterns - set(CALL_SITES) - KNOWN_UNWIRED == set(), (
        "schema pattern without a listed call site"
    )
    assert (set(CALL_SITES) | KNOWN_UNWIRED) - patterns == set(), (
        "stale entry: pattern no longer in the schema"
    )
    assert not (set(CALL_SITES) & KNOWN_UNWIRED)


@pytest.mark.parametrize("pattern", sorted(CALL_SITES))
def test_call_site_records_the_pattern(pattern):
    for rel, needle in CALL_SITES[pattern]:
        text = (PLUGIN / rel).read_text(encoding="utf-8")
        assert needle in text, f"{pattern}: {rel} no longer contains {needle!r}"


def test_every_family_has_at_least_one_recording_site():
    for family, spec in A.load_schema()["families"].items():
        wired = [p for p in spec["patterns"] if p in CALL_SITES]
        assert wired, f"family {family} has no recording call site"


# --- atlas_analytics_hot: the stdlib-only writer the per-event hooks use ----------------------------
import itertools  # noqa: E402

import atlas_analytics_hot as H  # noqa: E402


def test_hot_module_constants_match_the_client():
    assert H.OFF_VALUES == A.OFF_VALUES
    assert H.ON_VALUES == A.ON_VALUES
    assert H.AUTOMATION_VARS == A.AUTOMATION_VARS


def test_hot_enabled_agrees_with_client_state_on_every_opt_out_combination(tmp_path, monkeypatch):
    for var in ("DO_NOT_TRACK", "ATLAS_ANALYTICS", *A.AUTOMATION_VARS):
        monkeypatch.delenv(var, raising=False)
    monkeypatch.setenv("ATLAS_HOME", str(tmp_path))
    settings, consent = tmp_path / "settings.json", tmp_path / "analytics" / "consent.json"
    consent.parent.mkdir()
    cases = itertools.product(
        (None, "1", "0", "false", "yes"),  # DO_NOT_TRACK
        (None, "on", "off", "OFF", "0", "garbage"),  # ATLAS_ANALYTICS env
        (None, "off", "on", "x", 7),  # settings.json env knob
        (None, True, False),  # consent.json enabled
        (None, "CI", "PYTEST_CURRENT_TEST"),  # automation guard
    )
    n = 0
    for dnt, env, store, chosen, auto in cases:
        for var, val in (("DO_NOT_TRACK", dnt), ("ATLAS_ANALYTICS", env)):
            monkeypatch.delenv(var, raising=False)
            if val is not None:
                monkeypatch.setenv(var, val)
        for var in ("CI", "PYTEST_CURRENT_TEST"):
            monkeypatch.delenv(var, raising=False)
        if auto:
            monkeypatch.setenv(auto, "1")
        settings.write_text(json.dumps({"env": {"ATLAS_ANALYTICS": store}}) if store is not None else "{}")
        consent.write_text(json.dumps({"enabled": chosen}) if chosen is not None else "{}")
        A._reset()
        assert H.enabled() == A.state()[0], (dnt, env, store, chosen, auto, A.state())
        n += 1
    A._reset()
    assert n == 5 * 6 * 5 * 3 * 3


def test_hot_record_lines_are_accepted_by_the_client_and_bad_keys_are_dropped(tmp_path, monkeypatch):
    for var in ("DO_NOT_TRACK", "ATLAS_ANALYTICS", *A.AUTOMATION_VARS):
        monkeypatch.delenv(var, raising=False)
    monkeypatch.setenv("ATLAS_HOME", str(tmp_path))
    monkeypatch.setenv("ATLAS_ANALYTICS", "on")
    A._reset()
    H.record(["dispatch.PreToolUse.ms.lt50", "gate.pass", "hook.git_guard.slow", "has space", "/etc/passwd", "x" * 97, 5, ""])
    H.record(["skill.atlas-plan"], n=2)
    lines = (tmp_path / "analytics" / "events.jsonl").read_text().splitlines()
    keys = [json.loads(ln)["k"] for ln in lines]
    assert keys == ["dispatch.PreToolUse.ms.lt50", "gate.pass", "hook.git_guard.slow", "skill.atlas-plan"]
    got = {e["k"]: e["n"] for e in A.read_events()}
    assert got == {k: (2 if k == "skill.atlas-plan" else 1) for k in keys}
    assert all(e["w"] == A._week_of(A._now()) for e in A.read_events())
    monkeypatch.setenv("ATLAS_ANALYTICS", "off")
    H.record(["gate.pass"])
    assert len((tmp_path / "analytics" / "events.jsonl").read_text().splitlines()) == len(lines)
    A._reset()


def test_a_planted_bad_line_never_reaches_the_payload(tmp_path, monkeypatch):
    monkeypatch.setenv("ATLAS_HOME", str(tmp_path))
    monkeypatch.setenv("ATLAS_ANALYTICS", "on")
    A._reset()
    H.record(["skill.my-private-skill", "hook.not_a_hook.slow", "gate.pass"])
    payload = A.build_payload(A.pending_week())
    assert payload["counts"] == {"gate.pass": 1}
    A._reset()
